-- AgriCare AI Supabase backend
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,language text default 'English',created_at timestamptz default now());
create table if not exists public.scans(id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,disease_name text not null,confidence text,image_path text,created_at timestamptz default now());
create table if not exists public.reminders(id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,title text not null,reminder_date date,reminder_type text,created_at timestamptz default now());
create table if not exists public.favourites(id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,product_name text not null,created_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.scans enable row level security; alter table public.reminders enable row level security; alter table public.favourites enable row level security;
drop policy if exists "profile_select" on public.profiles; create policy "profile_select" on public.profiles for select using(auth.uid()=id);
drop policy if exists "profile_insert" on public.profiles; create policy "profile_insert" on public.profiles for insert with check(auth.uid()=id);
drop policy if exists "profile_update" on public.profiles; create policy "profile_update" on public.profiles for update using(auth.uid()=id);
drop policy if exists "scan_select" on public.scans; create policy "scan_select" on public.scans for select using(auth.uid()=user_id);
drop policy if exists "scan_insert" on public.scans; create policy "scan_insert" on public.scans for insert with check(auth.uid()=user_id);
drop policy if exists "scan_delete" on public.scans; create policy "scan_delete" on public.scans for delete using(auth.uid()=user_id);
drop policy if exists "reminder_select" on public.reminders; create policy "reminder_select" on public.reminders for select using(auth.uid()=user_id);
drop policy if exists "reminder_insert" on public.reminders; create policy "reminder_insert" on public.reminders for insert with check(auth.uid()=user_id);
drop policy if exists "reminder_delete" on public.reminders; create policy "reminder_delete" on public.reminders for delete using(auth.uid()=user_id);
drop policy if exists "fav_select" on public.favourites; create policy "fav_select" on public.favourites for select using(auth.uid()=user_id);
drop policy if exists "fav_insert" on public.favourites; create policy "fav_insert" on public.favourites for insert with check(auth.uid()=user_id);
drop policy if exists "fav_delete" on public.favourites; create policy "fav_delete" on public.favourites for delete using(auth.uid()=user_id);
insert into storage.buckets(id,name,public) values('crop-images','crop-images',false) on conflict(id) do nothing;
drop policy if exists "crop_upload" on storage.objects; create policy "crop_upload" on storage.objects for insert to authenticated with check(bucket_id='crop-images' and (storage.foldername(name))[1]=auth.uid()::text);
drop policy if exists "crop_read" on storage.objects; create policy "crop_read" on storage.objects for select to authenticated using(bucket_id='crop-images' and (storage.foldername(name))[1]=auth.uid()::text);
drop policy if exists "crop_delete" on storage.objects; create policy "crop_delete" on storage.objects for delete to authenticated using(bucket_id='crop-images' and (storage.foldername(name))[1]=auth.uid()::text);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,new.raw_user_meta_data->>'full_name') on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();